     1	/**
     2	 * Runs semantic-release in dry-run mode against a branch and prints the
     3	 * computed next release version, so a PR that would never publish (or that
     4	 * would recompute the hand-published 1.0.0 baseline) is caught before
     5	 * merge. Dependency-free (Node built-ins only) so it runs on a bare CI
     6	 * runner. Run via `bun run release:dry-run`.
     7	 */
     8	import { spawnSync } from 'node:child_process';
     9	import * as path from 'node:path';
    10	import { fileURLToPath } from 'node:url';
    11	
    12	const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
    13	
    14	function fail(message: string): never {
    15	  console.error(`FAIL: ${message}`);
    16	  process.exit(1);
    17	}
    18	
    19	function resolveBranch(): string {
    20	  const envBranch = process.env.DRY_RUN_BRANCH;
    21	  if (envBranch && envBranch.trim()) return envBranch.trim();
    22	
    23	  const result = spawnSync('git', ['rev-parse', '--abbrev-ref', 'HEAD'], {
    24	    cwd: REPO_ROOT,
    25	    encoding: 'utf-8',
    26	  });
    27	  if (result.status !== 0 || !result.stdout.trim()) {
    28	    fail(`could not resolve current branch: ${result.stderr}`);
    29	  }
    30	  return result.stdout.trim();
    31	}
    32	
    33	function main(): void {
    34	  const branch = resolveBranch();
    35	  console.log(`==> semantic-release --dry-run against branch "${branch}"`);
    36	
    37	  const semanticReleaseBin = path.join(REPO_ROOT, 'node_modules', 'semantic-release', 'bin', 'semantic-release.js');
    38	  const result = spawnSync(
    39	    'node',
    40	    [semanticReleaseBin, '--dry-run', '--no-ci', '--branches', branch],
    41	    {
    42	      cwd: REPO_ROOT,
    43	      encoding: 'utf-8',
    44	      env: {
    45	        ...process.env,
    46	        SEMANTIC_RELEASE_DRY_RUN: 'true',
    47	        // On GitHub Actions `pull_request` events GITHUB_REF is `refs/pull/<n>/merge`,
    48	        // and env-ci hands that to semantic-release as the current branch. `--no-ci`
    49	        // only skips the pull-request early return, not branch detection, so the run
    50	        // would end with "configured to only publish from <branch>" and exit 0 without
    51	        // analyzing anything. Steer env-ci at the branch actually being dry-run instead.
    52	        // Outside GitHub Actions env-ci ignores both variables and asks git.
    53	        GITHUB_EVENT_NAME: 'push',
    54	        GITHUB_REF: `refs/heads/${branch}`,
    55	      },
    56	    },
    57	  );
    58	
    59	  const combinedOutput = `${result.stdout ?? ''}${result.stderr ?? ''}`;
    60	  process.stdout.write(result.stdout ?? '');
    61	  process.stderr.write(result.stderr ?? '');
    62	
    63	  if (result.status !== 0) {
    64	    fail(`semantic-release --dry-run exited with status ${result.status}`);
    65	  }
    66	
    67	  const versionMatch = combinedOutput.match(/the next release version is (\d+\.\d+\.\d+)/i);
    68	  if (!versionMatch) {
    69	    console.log('==> no release would be triggered by this branch');
    70	    process.exit(0);
    71	  }
    72	
    73	  const nextVersion = versionMatch[1];
    74	  if (nextVersion === '1.0.0') {
    75	    fail('computed next release version is 1.0.0 — the v1.0.0 baseline must never be recomputed. Verify the v1.0.0 tag is reachable.');
    76	  }
    77	
    78	  console.log(`==> next release version: ${nextVersion}`);
    79	}
    80	
    81	main();

